CREATE OR REPLACE FUNCTION public.add_party_request(p_code text,p_track jsonb,p_nickname text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.parties; result uuid; idx integer; titles text[]:=ARRAY['Música Exemplo Um','Batida de Teste','Refrão Imaginário','Pista Simulada','Canção de Mentirinha','Hit Fictício do Verão','Balada de Amostra','Groove Inventado']; channels text[]:=ARRAY['Canal Fictício','Artista Demo','Banda Placeholder','DJ Exemplo','Coral Demo','Canal Fictício','Artista Demo','DJ Exemplo']; durations text[]:=ARRAY['3:24','2:58','4:10','3:45','3:02','2:49','4:33','3:17']; hues integer[]:=ARRAY[305,150,250,20,90,200,340,60]; canonical jsonb; BEGIN SELECT * INTO p FROM public.parties WHERE code=upper(trim(p_code)) FOR UPDATE; IF NOT FOUND OR p.status<>'ativa' THEN RAISE EXCEPTION 'Festa indisponível ou encerrada'; END IF; idx:=array_position(ARRAY['demo-1','demo-2','demo-3','demo-4','demo-5','demo-6','demo-7','demo-8'],p_track->>'id'); IF idx IS NULL THEN RAISE EXCEPTION 'Música inválida'; END IF; canonical:=jsonb_build_object('id','demo-'||idx,'title',titles[idx],'channel',channels[idx],'duration',durations[idx],'hue',hues[idx]); INSERT INTO public.queue_entries(party_id,track,requested_by) VALUES(p.id,canonical,COALESCE(NULLIF(left(trim(p_nickname),20),''),'Convidado')) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.add_party_request(text,jsonb,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.add_party_request(text,jsonb,text) TO anon,authenticated,service_role;